3	#include <charconv>
4	#include <cstdint>
5	#include <string>
6	#include <string_view>
7	#include <system_error>
8	#include <utility>
9	#include <vector>
10	
11	#include "file_digest_internal.h"
12	
13	namespace branchaudit {
14	
15	Digest merkle_empty_root() {
16	    // SHA-256 对空字节序列（不追加任何 Merkle 前缀）。
17	    return Sha256{}.final();
18	}
19	
20	Digest merkle_leaf(const unsigned char* data, std::size_t size) {
21	    Sha256 sha;
22	    const unsigned char prefix = 0x00;
23	    sha.update(&prefix, 1);
24	    sha.update(data, size);
25	    return sha.final();
26	}
27	
28	Digest merkle_parent(const Digest& left, const Digest& right) {
29	    Sha256 sha;
30	    const unsigned char prefix = 0x01;
31	    sha.update(&prefix, 1);
32	    sha.update(left.data(), left.size());
33	    sha.update(right.data(), right.size());
34	    return sha.final();
35	}
36	
37	namespace {
38	
39	// 流式计算单个文件的叶子摘要 SHA-256(0x00 || file bytes)。
40	// 定位、打开、分块读取与失败处理与 sha256_file 共用同一实现：唯一区别是
41	// 在文件字节之前加入一次单个 0x00 前缀字节（空文件也存在，且不随分块重复）。
42	FileHashResult leaf_file(const std::filesystem::path& path) {
43	    static constexpr unsigned char kLeafPrefix = 0x00;
44	    return internal::sha256_file_digest(path, &kLeafPrefix);
45	}
46	
47	// 计算有序批次的叶子层。严格按 paths 下标顺序：不排序、不去重。
48	// 任一文件失败立即返回该错误，不读取也不使用其后的任何文件。
49	std::string leaf_level(const std::vector<std::filesystem::path>& paths,
50	                       std::vector<Digest>& level) {
51	    level.clear();
52	    level.reserve(paths.size());
53	    for (const std::filesystem::path& path : paths) {
54	        FileHashResult leaf = leaf_file(path);
55	        if (!leaf.ok()) {
56	            return std::move(leaf.error);
57	        }
58	        level.push_back(leaf.digest);
59	    }
60	    return {};
61	}
62	
63	// 批次合并规则（root 与 prove 共用的唯一一份实现）：对当前层做一次相邻
64	// 配对——相邻节点按先左后右两两用 merkle_parent 合并；若该层节点数为
65	// 奇数，最后一个没有伙伴的节点摘要原样进入上一层（不复制、不补零）。
66	// 输入层不被修改，返回合并后的上一层；输入只有一个节点时返回的层同样
67	// 只有该节点本身。
68	std::vector<Digest> combine_level(const std::vector<Digest>& level) {
69	    std::vector<Digest> next;
70	    const bool odd = (level.size() % 2) != 0;
71	    next.reserve(level.size() / 2 + (odd ? 1 : 0));
72	    for (std::size_t i = 0; i + 1 < level.size(); i += 2) {
73	        next.push_back(merkle_parent(level[i], level[i + 1]));
74	    }
75	    if (odd) {
76	        next.push_back(level.back());
77	    }
78	    return next;
79	}
80	
81	// ---- prove 版本 1 JSON 的严格读取 -----------------------------------------
82	//
83	// 只实现 prove 已公开的格式所需的 JSON 子集：对象、数组、字符串、整数。
84	// 不接受小数、指数、null/true/false 作为字段值；空白与字段次序按 JSON
85	// 规则自由；重复字段、未知字段与对象之后的多余内容一律判错。解析器只
86	// 扫描传入文本，不做任何文件或内存映射 I/O。
87	
88	struct JsonParser {
89	    std::string_view text;
90	    std::size_t pos = 0;
91	    std::string error;
92	
93	    void ws() {
94	        while (pos < text.size()) {
95	            const char c = text[pos];
96	            if (c == ' ' || c == '\t' || c == '\n' || c == '\r') {
97	                ++pos;
98	            } else {
99	                break;
100	            }
101	        }
102	    }
103	
104	    bool eof() const { return pos >= text.size(); }
105	
106	    char peek() const { return text[pos]; }
107	
108	    bool fail(std::string msg) {
109	        // 每个调用点只会在尚未出错时进入；保留第一条原因。
110	        if (error.empty()) {
111	            error = std::move(msg);
112	        }
113	        return false;
114	    }
115	
116	    // 读取一个 JSON 字符串字面量（text[pos] 必须是 '"'），把解码后的
117	    // UTF-8 内容写入 out。prove 的摘要/字段名/side 都只含 ASCII，这里仍
118	    // 按 JSON 规则处理转义与 uXXXX（含代理对），以便对任意输入给出确定
119	    // 结果而非越界读取。
120	    bool read_string(std::string& out) {
121	        out.clear();
122	        ++pos;  // 跳过起始引号
123	        while (true) {
124	            if (eof()) {
125	                return fail("unterminated JSON string");
126	            }
127	            const char c = text[pos++];
128	            if (static_cast<unsigned char>(c) < 0x20) {
129	                return fail("unescaped control character in JSON string");
130	            }
131	            if (c == '"') {
132	                return true;
133	            }
134	            if (c == '\\') {
135	                if (eof()) {
136	                    return fail("unterminated escape in JSON string");
137	                }
138	                const char e = text[pos++];
139	                switch (e) {
140	                    case '"': out.push_back('"'); break;
141	                    case '\\': out.push_back('\\'); break;
142	                    case '/': out.push_back('/'); break;
143	                    case 'b': out.push_back('\b'); break;
144	                    case 'f': out.push_back('\f'); break;
145	                    case 'n': out.push_back('\n'); break;
146	                    case 'r': out.push_back('\r'); break;
147	                    case 't': out.push_back('\t'); break;
148	                    case 'u': {
149	                        std::uint32_t cp = 0;
150	                        if (!read_hex4(cp)) {
151	                            return fail("invalid \\u escape in JSON string");
152	                        }
153	                        // UTF-16 代理对：\uD800-\uDBFF 后必须紧跟
154	                        // \uDC00-\uDFFF。
155	                        if (cp >= 0xD800 && cp <= 0xDBFF) {
156	                            if (pos + 1 < text.size() && text[pos] == '\\' &&
157	                                text[pos + 1] == 'u') {
158	                                pos += 2;
159	                                std::uint32_t lo = 0;
160	                                if (!read_hex4(lo) || lo < 0xDC00 ||
161	                                    lo > 0xDFFF) {
162	                                    return fail("invalid UTF-16 surrogate pair "
163	                                                "in JSON string");
164	                                }
165	                                cp = 0x10000 + ((cp - 0xD800) << 10) +
166	                                     (lo - 0xDC00);
167	                            } else {
168	                                return fail("lone UTF-16 high surrogate in JSON "
169	                                            "string");
170	                            }
171	                        } else if (cp >= 0xDC00 && cp <= 0xDFFF) {
172	                            return fail("lone UTF-16 low surrogate in JSON "
173	                                        "string");
174	                        }
175	                        append_utf8(cp, out);
176	                        break;
177	                    }
178	                    default:
179	                        return fail("invalid escape sequence in JSON string");
180	                }
181	            } else {
182	                out.push_back(c);
183	            }
184	        }
185	    }
186	
187	    // 从 text[pos..pos+4) 读取四个十六进制位；不足或非法返回 false。
188	    bool read_hex4(std::uint32_t& out) {
189	        if (pos + 4 > text.size()) {
190	            return false;
191	        }
192	        std::uint32_t v = 0;
193	        for (int i = 0; i < 4; ++i) {
194	            const char c = text[pos++];
195	            v <<= 4;
196	            if (c >= '0' && c <= '9') {
197	                v |= static_cast<std::uint32_t>(c - '0');
198	            } else if (c >= 'a' && c <= 'f') {
199	                v |= static_cast<std::uint32_t>(c - 'a' + 10);
200	            } else if (c >= 'A' && c <= 'F') {
201	                v |= static_cast<std::uint32_t>(c - 'A' + 10);
202	            } else {
203	                return false;
204	            }
205	        }
206	        out = v;
207	        return true;
208	    }
209	
210	    static void append_utf8(std::uint32_t cp, std::string& out) {
211	        if (cp <= 0x7F) {
212	            out.push_back(static_cast<char>(cp));
213	        } else if (cp <= 0x7FF) {
214	            out.push_back(static_cast<char>(0xC0 | (cp >> 6)));
215	            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
216	        } else if (cp <= 0xFFFF) {
217	            out.push_back(static_cast<char>(0xE0 | (cp >> 12)));
218	            out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
219	            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
220	        } else {
221	            out.push_back(static_cast<char>(0xF0 | (cp >> 18)));
222	            out.push_back(static_cast<char>(0x80 | ((cp >> 12) & 0x3F)));
223	            out.push_back(static_cast<char>(0x80 | ((cp >> 6) & 0x3F)));
224	            out.push_back(static_cast<char>(0x80 | (cp & 0x3F)));
225	        }
226	    }
227	
228	    // 扫描一个 JSON 数字的语法区间并在必须为无符号整数时拒绝非整数写法。
229	    // must_be_uint 为真时：不得有符号/小数/指数；成功时 [start,pos) 即
230	    // 一段 0..2^64-1 的十进制数字（是否超界由 read_uint64 用 from_chars
231	    // 判定）。返回 [start,pos) 长度便于调用方取出数字串。
232	    bool scan_number(bool must_be_uint, std::size_t& start, std::size_t& end) {
233	        start = pos;
234	        if (!eof() && peek() == '-') {
235	            ++pos;
236	            if (must_be_uint) {
237	                return fail("negative integer is not allowed");
238	            }
239	        }
240	        // 整数部分：JSON 不允许前导 0（"0" 之后不能再跟数字）。
241	        if (eof() || peek() < '0' || peek() > '9') {
242	            return fail("invalid JSON number");
243	        }
244	        if (peek() == '0') {
245	            ++pos;
246	            if (!eof() && peek() >= '0' && peek() <= '9') {
247	                return fail("leading zeros are not allowed in JSON numbers");
248	            }
249	        } else {
250	            while (!eof() && peek() >= '0' && peek() <= '9') {
251	                ++pos;
252	            }
253	        }
254	        bool fraction_or_exponent = false;
255	        if (!eof() && peek() == '.') {
256	            fraction_or_exponent = true;
257	            ++pos;
258	            if (eof() || peek() < '0' || peek() > '9') {
259	                return fail("invalid JSON fraction");
260	            }
261	            while (!eof() && peek() >= '0' && peek() <= '9') {
262	                ++pos;
263	            }
264	        }
265	        if (!eof() && (peek() == 'e' || peek() == 'E')) {
266	            fraction_or_exponent = true;
267	            ++pos;
268	            if (!eof() && (peek() == '+' || peek() == '-')) {
269	                ++pos;
270	            }
271	            if (eof() || peek() < '0' || peek() > '9') {
272	                return fail("invalid JSON exponent");
273	            }
274	            while (!eof() && peek() >= '0' && peek() <= '9') {
275	                ++pos;
276	            }
277	        }
278	        if (must_be_uint && fraction_or_exponent) {
279	            // 1.0、1e0 这类写法在 JSON 里是数字，但不是“JSON 整数”，
280	            // leaf_count/leaf_index/version 必须准确保留整数值。
281	            return fail("only JSON integers are accepted for this field");
282	        }
283	        end = pos;
284	        return true;
285	    }
286	
287	    // 读取字段值位置上的无符号 64 位 JSON 整数。
288	    bool read_uint64(std::uint64_t& out, std::string_view field) {
289	        ws();
290	        if (eof()) {
291	            return fail(std::string("missing value for field \"") +
292	                        std::string(field) + "\"");
293	        }
294	        const char c = peek();
295	        if (c == '"') {
296	            return fail(std::string("field \"") + std::string(field) +
297	                        "\" must be a JSON integer, got a string");
298	        }
299	        if (c == 't' || c == 'f' || c == 'n') {
300	            return fail(std::string("field \"") + std::string(field) +
301	                        "\" must be a JSON integer, got a boolean or null");
302	        }
303	        if (c == '{' || c == '[') {
304	            return fail(std::string("field \"") + std::string(field) +
305	                        "\" must be a JSON integer, got a container");
306	        }
307	        if (c != '-' && (c < '0' || c > '9')) {
308	            return fail(std::string("field \"") + std::string(field) +
309	                        "\" has an invalid value");
310	        }
311	        std::size_t start = 0;
312	        std::size_t end = 0;
313	        if (!scan_number(/*must_be_uint=*/true, start, end)) {
314	            return false;
315	        }
316	        const std::string_view digits(text.data() + start, end - start);
317	        const auto res = std::from_chars(
318	            digits.data(), digits.data() + digits.size(), out);
319	        if (res.ec != std::errc{} ||
320	            res.ptr != digits.data() + digits.size()) {
321	            return fail(std::string("field \"") + std::string(field) +
322	                        "\" integer is out of unsigned 64-bit range");
323	        }
324	        return true;
325	    }
326	
327	    // 读取字段值位置上的 JSON 字符串。
328	    bool read_string_value(std::string& out, std::string_view field) {
329	        ws();
330	        if (eof()) {
331	            return fail(std::string("missing value for field \"") +
332	                        std::string(field) + "\"");
333	        }
334	        const char c = peek();
335	        if (c != '"') {
336	            return fail(std::string("field \"") + std::string(field) +
337	                        "\" must be a JSON string");
338	        }
339	        return read_string(out);
340	    }
341	};
