343	// 把恰好 64 个小写十六进制字符还原为 32 字节摘要。长度不符、含非十六
344	// 进制字符或使用大写字符都明确失败：不截断、不替换损坏内容。
345	bool parse_digest_hex(const std::string& hex, Digest& out) {
346	    if (hex.size() != 64) {
347	        return false;
348	    }
349	    auto nibble = [](char c, unsigned int& v) -> bool {
350	        if (c >= '0' && c <= '9') {
351	            v = static_cast<unsigned int>(c - '0');
352	            return true;
353	        }
354	        // 只接受小写：A-F 等大写字符在此失败，而不是被当作同一摘要。
355	        if (c >= 'a' && c <= 'f') {
356	            v = static_cast<unsigned int>(c - 'a' + 10);
357	            return true;
358	        }
359	        return false;
360	    };
361	    for (std::size_t i = 0; i < 32; ++i) {
362	        unsigned int hi = 0;
363	        unsigned int lo = 0;
364	        if (!nibble(hex[2 * i], hi) || !nibble(hex[2 * i + 1], lo)) {
365	            return false;
366	        }
367	        out[i] = static_cast<std::uint8_t>((hi << 4) | lo);
368	    }
369	    return true;
370	}
371	
372	// 读取字段值位置上的摘要字符串：恰好 64 个小写十六进制字符。
373	bool read_digest_value(JsonParser& p, Digest& out, std::string_view field) {
374	    std::string raw;
375	    if (!p.read_string_value(raw, field)) {
376	        return false;
377	    }
378	    if (!parse_digest_hex(raw, out)) {
379	        return p.fail(std::string("field \"") + std::string(field) +
380	                      "\" must be exactly 64 lowercase hexadecimal characters "
381	                      "decoding to 32 bytes");
382	    }
383	    return true;
384	}
