528	MerkleProofResult merkle_proof_file(
529	        const std::vector<std::filesystem::path>& paths,
530	        std::uint64_t leaf_index) {
531	    MerkleProofResult result;
532	
533	    // 位置必须落在批次内；空批次没有任何合法位置。
534	    if (leaf_index >= paths.size()) {
535	        result.error = "leaf index " + std::to_string(leaf_index) +
536	                       " out of range for batch of " +
537	                       std::to_string(paths.size()) + " file(s)";
538	        return result;
539	    }
540	
541	    // 叶子层：与 merkle_root_files 完全相同的文件与顺序规则。
542	    std::vector<Digest> level;
543	    result.error = leaf_level(paths, level);
544	    if (!result.ok()) {
545	        return result;
546	    }
547	
548	    MerkleProof& proof = result.proof;
549	    proof.leaf_count = paths.size();
550	    proof.leaf_index = leaf_index;
551	    proof.leaf = level[static_cast<std::size_t>(leaf_index)];
552	
553	    // 沿被选位置逐层向上：每层只记录实际存在的兄弟；奇数末节点原样
554	    // 提升的层没有兄弟，不添加记录（不复制末节点、不补零）。该层如何
555	    // 合并与 root 完全相同——两者都调用同一份 combine_level。
556	    std::size_t idx = static_cast<std::size_t>(leaf_index);
557	    while (level.size() > 1) {
558	        if (idx % 2 == 0) {
559	            if (idx + 1 < level.size()) {
560	                proof.siblings.push_back(
561	                    {MerkleSibling::Side::right, level[idx + 1]});
562	            }
563	            // idx 是奇数层的末节点：经 combine_level 原样提升，无兄弟记录。
564	        } else {
565	            proof.siblings.push_back(
566	                {MerkleSibling::Side::left, level[idx - 1]});
567	        }
568	
569	        idx /= 2;
570	        level = combine_level(level);
571	    }
572	
573	    proof.root = level.front();
574	    return result;
575	}
