// branchaudit 有序文件批次 Merkle 根与单文件成员证明回归测试
//（无第三方依赖，链接 branchaudit_core）。
//
// 预期摘要的独立依据：全部常量由 Python hashlib（底层系统 OpenSSL 的
// SHA-256）按公开字节规则（叶子 SHA-256(0x00||data)、父节点
// SHA-256(0x01||left||right)、奇数末节点原样提升、空批次为 SHA-256("")）
// 独立计算，不使用本项目代码生成期望值。
//
// 运行成功返回 0；任一断言失败返回非零。

#include <array>
#include <cstddef>
#include <cstdint>
#include <filesystem>
#include <fstream>
#include <functional>
#include <iostream>
#include <sstream>
#include <string>
