        MerkleProofParseResult r =
            expect_parse_ok(right_text, "escaped right sibling with newline");
        if (r.ok()) {
            check(r.proof.siblings.size() == 1 &&
                      r.proof.siblings[0].side == MerkleSibling::Side::right &&
                      r.proof.siblings[0].digest == labc,
