    top_with_root_key("a\\u", "\\u with no hex digits");
    top_with_root_key("a\\u00G0", "\\u with non-hex G");
    top_with_root_key("a\\u00g0", "\\u with non-hex lowercase g");
    top_with_root_key("a\\u0 30", "\\u with space in hex digits");
    top_with_root_key("a\\u00-0", "\\u with minus in hex digits");
    top_with_root_key("a\\u003", "\\u cut at end of object key");

    // 损坏转义出现在字符串值里：摘要、side 与兄弟字段名三种位置。
    expect_parse_fail(
        "{\"version\":1,\"root\":\"\\u006" + hex.substr(1) +
            "\",\"leaf_count\":1,\"leaf_index\":0,\"leaf\":\"" + hex +
            "\",\"siblings\":[]}",
        "truncated \\u escape inside root digest");
    expect_parse_fail(
        "{\"version\":1,\"root\":\"" + hex +
            "\",\"leaf_count\":1,\"leaf_index\":0,\"leaf\":\"" +
            "\\u00G0" + hex.substr(1) + "\",\"siblings\":[]}",
        "non-hex digit in \\u escape inside leaf digest");
    {
        const Digest pair_root = branchaudit::merkle_parent(la, labc);
        expect_parse_fail(
            "{\"version\":1,\"root\":\"" + hex_of(pair_root) +
                "\",\"leaf_count\":2,\"leaf_index\":0,\"leaf\":\"" +
                hex_of(la) +
                "\",\"siblings\":[{\"side\":\"righ\\u007\",\"digest\":\"" +
                hex_of(labc) + "\"}]}",
            "truncated \\u escape inside sibling side");
        expect_parse_fail(
            "{\"version\":1,\"root\":\"" + hex_of(pair_root) +
                "\",\"leaf_count\":2,\"leaf_index\":0,\"leaf\":\"" +
                hex_of(la) +
                "\",\"siblings\":[{\"sid\\u00G0\":\"right\",\"digest\":\"" +
                hex_of(labc) + "\"}]}",
            "non-hex \\u escape inside sibling field name");
    }

    // 损坏片段不得被“吃掉后继续”：非法字符在转义之后，也不能忽略
    // 转义、把后面的字符拼出合法字段名而成功。
    expect_parse_fail(
        "{\"roo\\u00G0t\":\"x\"}",
        "corrupt escape not skipped to recover a field name");

    // 反斜杠后直接到文本结尾：不是合法转义。
    expect_parse_fail("{\"abc\\", "trailing backslash at end of text");
}

