    // 而不是按转义损坏失败，也不产生替换字符。
    expect_parse_fail("{\"\\uD83D\\uDE00\":1}",
                      "valid surrogate pair decodes (then unknown field)");
    side_proof("\"\\uD83D\\uDE00\"",
               "valid surrogate pair in side decodes (then not left/right)");

    // 合法代理对出现在合法摘要串之外没有成功路径，但可确认它确实解码
    // 成四个 UTF-8 字节而不是被替换：用一个“未知字段”错误信息包含
    // 该字符无法直接断言，这里改为确认读取成功的等价场景不存在数据
    // 丢失——通过把字段名写成“合法代理对字符 + 正常后缀”仍按未知字段
    // 拒绝（证明解析器消费了完整代理对而非截断）。
    expect_parse_fail(
        "{\"\\uD83D\\uDE00x\":1,\"version\":1}",
        "full surrogate pair consumed before rejecting unknown field");
}

